import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"16、【豫】 坤下震上","description":"温公易说 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"温公易说 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"zh/classics/wengong/017.md","filePath":"zh/classics/wengong/017.md"}'),n={name:"zh/classics/wengong/017.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><h3 id="彖曰-豫-刚应而志行-顺以动-豫。豫顺以动-故天地如之-而况建侯行师乎-天地以顺动-故日月不过-而四时不忒。圣人以顺动-则刑罚清而民服。豫之时义-大矣哉" tabindex="-1">彖曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过，而四时不忒。圣人以顺动，则刑罚清而民服。豫之时义，大矣哉！ <a class="header-anchor" href="#彖曰-豫-刚应而志行-顺以动-豫。豫顺以动-故天地如之-而况建侯行师乎-天地以顺动-故日月不过-而四时不忒。圣人以顺动-则刑罚清而民服。豫之时义-大矣哉" aria-label="Permalink to “彖曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过，而四时不忒。圣人以顺动，则刑罚清而民服。豫之时义，大矣哉！”">​</a></h3><h3 id="象曰-雷出地奋-豫。先王以作乐崇德-殷荐之上帝-以配祖考。" tabindex="-1">象曰：雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。 <a class="header-anchor" href="#象曰-雷出地奋-豫。先王以作乐崇德-殷荐之上帝-以配祖考。" aria-label="Permalink to “象曰：雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。”">​</a></h3><p>雷出地者，春分候也。春分之时，雷迅出地以动万物，万物莫不奋迅悦豫而从之也。豫，喜意也。作乐所以饰喜也。荐之上帝以配祖考，用乐之盛者。</p><h3 id="初六-鸣豫-凶-象曰-初六鸣豫-志穷凶也。" tabindex="-1">初六：鸣豫，凶 象曰：初六鸣豫，志穷凶也。 <a class="header-anchor" href="#初六-鸣豫-凶-象曰-初六鸣豫-志穷凶也。" aria-label="Permalink to “初六：鸣豫，凶 象曰：初六鸣豫，志穷凶也。”">​</a></h3><h3 id="六二-介于石-不终日-贞吉-象曰-不终日贞吉-以中正也。" tabindex="-1">六二：介于石，不终日，贞吉 象曰：不终日贞吉，以中正也。 <a class="header-anchor" href="#六二-介于石-不终日-贞吉-象曰-不终日贞吉-以中正也。" aria-label="Permalink to “六二：介于石，不终日，贞吉 象曰：不终日贞吉，以中正也。”">​</a></h3><h3 id="六三-盱豫-悔迟-有悔-象曰-盱豫有悔-位不当也。" tabindex="-1">六三：盱豫，悔迟，有悔 象曰：盱豫有悔，位不当也。 <a class="header-anchor" href="#六三-盱豫-悔迟-有悔-象曰-盱豫有悔-位不当也。" aria-label="Permalink to “六三：盱豫，悔迟，有悔 象曰：盱豫有悔，位不当也。”">​</a></h3><h3 id="九四-由豫-大有得-勿疑-朋盍簪-象曰-由豫大有得-志大行也。" tabindex="-1">九四：由豫，大有得，勿疑，朋盍簪 象曰：由豫大有得，志大行也。 <a class="header-anchor" href="#九四-由豫-大有得-勿疑-朋盍簪-象曰-由豫大有得-志大行也。" aria-label="Permalink to “九四：由豫，大有得，勿疑，朋盍簪 象曰：由豫大有得，志大行也。”">​</a></h3><h3 id="六五-贞疾-恒不死-象曰-六五贞疾-乘刚也。恒不死-中未亡也。" tabindex="-1">六五：贞疾，恒不死 象曰：六五贞疾，乘刚也。恒不死，中未亡也。 <a class="header-anchor" href="#六五-贞疾-恒不死-象曰-六五贞疾-乘刚也。恒不死-中未亡也。" aria-label="Permalink to “六五：贞疾，恒不死 象曰：六五贞疾，乘刚也。恒不死，中未亡也。”">​</a></h3><h3 id="上六-冥豫-成有渝-无咎-象曰-冥豫在上-何可长也。" tabindex="-1">上六：冥豫，成有渝，无咎 象曰：冥豫在上，何可长也。 <a class="header-anchor" href="#上六-冥豫-成有渝-无咎-象曰-冥豫在上-何可长也。" aria-label="Permalink to “上六：冥豫，成有渝，无咎 象曰：冥豫在上，何可长也。”">​</a></h3>',10)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
